public class TestPyramidDemo {
    static class Calculator {
        int add(int a, int b) { return a + b; }
    }
    static void assertEquals(int expected, int actual) {
        if (expected != actual)
            throw new AssertionError("Expected " + expected + " but got " + actual);
        System.out.println("PASS: add(3,4) = " + actual);
    }
    public static void main(String[] args) {
        Calculator calc = new Calculator();
        assertEquals(7, calc.add(3, 4));
        assertEquals(0, calc.add(-5, 5));
    }
}

import java.util.HashMap;
import java.util.Map;

public class ContractDemo {
    static void verifyContract(Map<String, Object> response, String requiredField) {
        if (response.containsKey(requiredField)) {
            System.out.println("PASS");
        } else {
            System.out.println("FAIL: missing " + requiredField);
        }
    }
    public static void main(String[] args) {
        Map<String, Object> validResponse = new HashMap<>();
        validResponse.put("userId", 42);
        validResponse.put("name", "Merlin");

        Map<String, Object> invalidResponse = new HashMap<>();
        invalidResponse.put("id", 42); // wrong field name

        verifyContract(validResponse, "userId");
        verifyContract(invalidResponse, "userId");
    }
}

public class PerformanceDemo {
    public static void main(String[] args) {
        int[] responseTimes = {120, 95, 140, 110, 200, 85, 130};
        int total = 0;
        for (int t : responseTimes) total += t;
        double avg = (double) total / responseTimes.length;
        double rps = 1000.0 / avg;
        System.out.printf("Avg response: %.0fms%n", avg);
        System.out.printf("Approx RPS: %.1f%n", rps);
    }
}

public class QualityDemo {
    static String qualityScore(int bugs, int codeSmells, int coverage) {
        if (bugs == 0 && coverage >= 80) return "Quality: GOOD";
        if (bugs == 0 && coverage >= 60) return "Quality: WARNING";
        return "Quality: POOR";
    }
    public static void main(String[] args) {
        System.out.println(qualityScore(0, 5, 85));
        System.out.println(qualityScore(0, 12, 65));
        System.out.println(qualityScore(3, 20, 40));
    }
}
